INSERT INTO security_menu (id, parent_id, menu_name, menu_type, sort, icon, path, visible, status, permission, tenant_id, create_op, create_time, modify_op, modify_time, deleted, delete_op, delete_time, position, owner, button_key, description) VALUES ('95775769', '94991641', '编辑', 3, 0, NULL, NULL, 1, 1, 'POST:security:/tablemodel/updateTableComment;POST:security:/tablemodel/column/updateComment;(main)POST:security:/tablemodel/foreignKey/save;DELETE:security:/tablemodel/foreignKey/delete', NULL, 'admin', '2026-05-19 21:32:51.899006', 'admin', '2026-05-19 21:32:51.899006', 0, NULL, NULL, 1, 1, '94991641_edit', '# 功能介绍
编辑表模型注释、字段注释、外键信息
# 界面布局
以抽屉的样式弹出 ，上中下布局 。
- 上面部分展示表的基本信息，只有`表注释`支持更改。
- 中间部分字段列表 ， 只有`字段注释`支持更改
- 下面部分外键信息 ，采集的数据只能修改`备注` ，自定义添加的支持修改所有信息
注释修改方式：点击输入框 -> 输入文本 -> 焦点脱离自动保存');
